package com.messenger.app.domain.delivery

/** Local delivery contracts, NOT a new wire format. No Android, HTTP or Room types.
 * Ciphertext is already Signal-encrypted per device before it enters this boundary.
 * Retry IDs are owned by the durable outbox, never generated by a transport. */
data class DeviceEnvelope(
    val recipientDeviceId: String,
    val messageType: Int,
    val ciphertext: String,
)

data class PreparedMessage(
    val conversationId: String,
    val clientMessageId: String,
    val envelopes: List<DeviceEnvelope>,
    /** Existing server attachment IDs. A future blob transport needs its own binding. */
    val attachmentIds: List<String> = emptyList(),
    val kind: String = "content",
    /** Legacy server target ID for reply/edit/delete/reaction; not an offline ID yet. */
    val targetMessageId: String? = null,
)

/** Captured BEFORE preparing envelopes. This is a local session generation, not a token. */
data class DeliveryContext(val sessionEpoch: Int)

data class ServerReceipt(
    val id: String,
    val chatId: String,
    val clientMessageId: String,
    val senderId: String,
    val sequence: Long,
    val createdAt: String,
    val status: String,
)

sealed interface DeliveryAcceptance {
    /** Means server custody only; it must never set recipient DELIVERED or READ. */
    data class ServerAccepted(val receipt: ServerReceipt) : DeliveryAcceptance
}

interface MessageTransport {
    /** One attempt. Failures propagate to the existing outbox policy; cancellation
     * propagates unchanged. No retries, encryption, persistence or UI mutations here. */
    suspend fun send(message: PreparedMessage, context: DeliveryContext): DeliveryAcceptance
}
